select job_title_group, is_remote, min_salary, level_list from (select case when job_title in ('Manager', 'Analyst') then 'core' else 'other' end as job_title_group, is_remote, min(salary) as min_salary, sort_array(collect_set(level)) as level_list from employees group by case when job_title in ('Manager', 'Analyst') then 'core' else 'other' end, is_remote) as t where min_salary >= 86000
